solution.solution.cpp:
#include <vector>

struct Item { float weight; };
struct Inventory { std::vector<Item*> slots; };
struct Player { Inventory* inventory{ nullptr }; };
struct World { Player* player{ nullptr }; };

float carriedWeight(const World& world)
{
    if (world.player == nullptr || world.player->inventory == nullptr) return 0.0f;
    float total{ 0.0f };
    for (const Item* item : world.player->inventory->slots)
        if (item != nullptr) total += item->weight;
    return total;
}

unitTests:
TEST("everything present")
{
    Item a{ 2.5f }, b{ 4.0f };
    Inventory bag{ { &a, &b } };
    Player p{ &bag };
    CHECK_NEAR(carriedWeight(World{ &p }), 6.5, 1e-6);
}
TEST("an empty slot is skipped")
{
    Item a{ 1.0f };
    Inventory bag{ { nullptr, &a, nullptr } };
    Player p{ &bag };
    CHECK_NEAR(carriedWeight(World{ &p }), 1.0, 1e-6);
}
TEST("no inventory") { Player p{ nullptr }; CHECK_NEAR(carriedWeight(World{ &p }), 0.0, 1e-9); }
TEST("no player") { CHECK_NEAR(carriedWeight(World{ nullptr }), 0.0, 1e-9); }
TEST("an empty bag") { Inventory bag{}; Player p{ &bag }; CHECK_NEAR(carriedWeight(World{ &p }), 0.0, 1e-9); }

